j2:forEach.script:
            var editor = CodeMirror.fromTextArea(document.getElementById('coverage_editor_$[jvar_field]'), {
                lineNumbers: true,
                lineWrapping: true,
                mode: 'javascript',
                gutters: ["CodeMirror-lint-markers", "CodeMirror-linenumbers", "CodeMirror-foldgutter"],
                theme: "snc_readonly",
                readOnly: true
            });

            editor.setValue('$[JS:jvar_script]');

			debugger;

            var STATE = {
                COVERED: 0,
                UNCOVERED: 1,
                NOTEXECUTABLE: 2
            };

            var getState = function(line, covered, uncovered) {
                if (covered.indexOf(line) != -1)
                    return STATE.COVERED;
                else if (uncovered.indexOf(line) != -1)
                    return STATE.UNCOVERED;
                else
                    return STATE.NOTEXECUTABLE;
            }

            var covered_lines = '$[jvar_covered_lines]'.replace(" ", "").split(',');
            var executable_lines = '$[jvar_executable_lines]'.replace('[', '')
                .replace(']', '').split(', ');
            var uncovered_lines = executable_lines.filter(function(line) {
                return covered_lines.indexOf(line) == -1;
            });

            var prevState = STATE.NOTEXECUTABLE;
            for (var line = 1; line != editor.lineCount() + 1; line++) {
                var state = getState(line.toString(), covered_lines, uncovered_lines);
                if (state == STATE.COVERED) {
                    editor.addLineClass(line - 1, "background", "codecoverage-covered");
                    if (prevState != STATE.COVERED)
                        editor.addLineClass(line - 1, "background", "codecoverage-covered-start");
                } else if (state == STATE.UNCOVERED) {
                    editor.addLineClass(line - 1, "background", "codecoverage-uncovered");
                    editor.addLineClass(line - 1, "gutter", "codecoverage-uncovered-gutter");
                    if (prevState != STATE.UNCOVERED)
                        editor.addLineClass(line - 1, "background", "codecoverage-uncovered-start");
                }
                prevState = state;
            }
            var prevState = STATE.NOTEXECUTABLE;
            for (var line = editor.lineCount(); line != 0; line--) {
                var state = getState(line.toString(), covered_lines, uncovered_lines);
                if (state == STATE.COVERED) {
                    if (prevState != STATE.COVERED)
                        editor.addLineClass(line - 1, "background", "codecoverage-covered-end");
                } else if (state == STATE.UNCOVERED) {
                    if (prevState != STATE.UNCOVERED)
                        editor.addLineClass(line - 1, "background", "codecoverage-uncovered-end");
                }
                prevState = state;
            }
